<?php namespace App\Domains\Comercial\LiveSales\Actions; use App\Domains\Comercial\LiveSales\Services\LiveSalesService; use App\Models\InteraccionLive; use App\Models\Lead; class ConvertirInteraccionLiveEnLeadAction{ public function __construct(private readonly LiveSalesService $service){} public function execute(InteraccionLive $interaccion):Lead{return $this->service->convertirEnLead($interaccion->loadMissing('sesionLive'));} }
